// SPDX-License-Identifier: LicenseRef-ArchLiquid-Proprietary
pragma solidity 0.8.30;

import {Ownable2Step, Ownable} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IUniswapV2Factory, IUniswapV2Pair} from "./interfaces/IUniswapV2.sol";

/// @title ArchLiquidityLocker
/// @notice Time-locked vaults for canonical Uniswap V2 LP tokens. The core
///         guarantee: once locked, nothing unlocks a position before its
///         unlock time. There is no admin path to locked funds; the owner
///         role only manages the fee exemption list (for the token factory)
///         and cannot touch vaults.
contract ArchLiquidityLocker is Ownable2Step, ReentrancyGuard {
    using SafeERC20 for IERC20;

    struct Lock {
        address token;
        address owner;
        uint256 amount;
        uint64 unlockTime;
        bool withdrawn;
    }

    /// @notice Flat creation fee, immutable so it can never be raised.
    uint256 public immutable FEE;
    address payable public immutable TREASURY;
    IUniswapV2Factory public immutable FACTORY;
    uint64 public constant MIN_DURATION = 30 days;

    Lock[] private _locks;
    /// @dev Protocol contracts (token factory, launchpad) create locks inside
    ///      flows that already charged their own fee.
    mapping(address => bool) public feeExempt;
    /// @dev Trusted protocol factories may exempt the child contracts they
    ///      deploy (e.g. the launchpad exempting each presale it spawns). The
    ///      only power granted is waiving the flat lock fee, never touching a
    ///      vault. Set by the owner (multisig).
    mapping(address => bool) public isFactory;

    event Locked(uint256 indexed id, address indexed token, address indexed owner, uint256 amount, uint64 unlockTime);
    event Withdrawn(uint256 indexed id, address indexed to, uint256 amount);
    event Relocked(uint256 indexed id, uint64 newUnlockTime);
    event LockOwnershipTransferred(uint256 indexed id, address indexed from, address indexed to);
    event FeeExemptSet(address indexed account, bool exempt);
    event FactorySet(address indexed factory, bool enabled);

    constructor(uint256 fee, address payable treasury, IUniswapV2Factory factory, address initialOwner)
        Ownable(initialOwner)
    {
        require(treasury != address(0), "locker: zero treasury");
        require(address(factory) != address(0) && address(factory).code.length > 0, "locker: invalid factory");
        FEE = fee;
        TREASURY = treasury;
        FACTORY = factory;
    }

    function lockCount() external view returns (uint256) {
        return _locks.length;
    }

    function getLock(uint256 id) external view returns (Lock memory) {
        return _locks[id];
    }

    function setFactory(address factory, bool enabled) external onlyOwner {
        isFactory[factory] = enabled;
        emit FactorySet(factory, enabled);
    }

    /// @notice Waive (or restore) the flat lock fee for `account`. Callable by
    ///         the owner or by a trusted protocol factory. This never moves
    ///         funds; it only sets whether `account` must pay the fee to lock.
    function setFeeExempt(address account, bool exempt) external {
        require(msg.sender == owner() || isFactory[msg.sender], "locker: not authorized");
        feeExempt[account] = exempt;
        emit FeeExemptSet(account, exempt);
    }

    /// @notice Lock `amount` of a canonical pair until `unlockTime`. Records
    ///         the balance actually received rather than trusting `amount`.
    /// @param lockOwner The address that may withdraw after unlock (the
    ///        factory passes the project creator here).
    function lock(IERC20 token, uint256 amount, uint64 unlockTime, address lockOwner)
        external
        payable
        nonReentrant
        returns (uint256 id)
    {
        require(amount > 0, "locker: zero amount");
        require(lockOwner != address(0), "locker: zero owner");
        require(unlockTime >= block.timestamp + MIN_DURATION, "locker: below min duration");
        require(isCanonicalPair(address(token)), "locker: non-canonical pair");
        _collectFee();

        uint256 before = token.balanceOf(address(this));
        token.safeTransferFrom(msg.sender, address(this), amount);
        uint256 received = token.balanceOf(address(this)) - before;
        require(received > 0, "locker: nothing received");

        id = _locks.length;
        _locks.push(
            Lock({token: address(token), owner: lockOwner, amount: received, unlockTime: unlockTime, withdrawn: false})
        );
        emit Locked(id, address(token), lockOwner, received, unlockTime);
    }

    /// @notice Withdraw a matured lock. Only the lock owner, only after
    ///         unlock time, only once.
    function withdraw(uint256 id) external nonReentrant {
        Lock storage l = _locks[id];
        require(msg.sender == l.owner, "locker: not lock owner");
        require(!l.withdrawn, "locker: already withdrawn");
        require(block.timestamp >= l.unlockTime, "locker: still locked");

        l.withdrawn = true;
        IERC20(l.token).safeTransfer(l.owner, l.amount);
        emit Withdrawn(id, l.owner, l.amount);
    }

    /// @notice Extend a lock. Strictly monotonic: the new unlock time must be
    ///         later than the current one. Shortening is impossible.
    function relock(uint256 id, uint64 newUnlockTime) external {
        Lock storage l = _locks[id];
        require(msg.sender == l.owner, "locker: not lock owner");
        require(!l.withdrawn, "locker: already withdrawn");
        require(newUnlockTime > l.unlockTime, "locker: can only extend");

        l.unlockTime = newUnlockTime;
        emit Relocked(id, newUnlockTime);
    }

    function transferLockOwnership(uint256 id, address newOwner) external {
        Lock storage l = _locks[id];
        require(msg.sender == l.owner, "locker: not lock owner");
        require(!l.withdrawn, "locker: already withdrawn");
        require(newOwner != address(0), "locker: zero owner");

        l.owner = newOwner;
        emit LockOwnershipTransferred(id, msg.sender, newOwner);
    }

    /// @notice Returns true only when `candidate` identifies itself as a pair
    ///         from FACTORY and FACTORY resolves the pair's two tokens back to
    ///         the exact candidate address. A token that merely mimics the pair
    ///         ABI cannot satisfy the factory lookup.
    function isCanonicalPair(address candidate) public view returns (bool) {
        if (candidate.code.length == 0) return false;

        IUniswapV2Pair pair = IUniswapV2Pair(candidate);
        address pairFactory;
        address token0;
        address token1;

        try pair.factory() returns (address value) {
            pairFactory = value;
        } catch {
            return false;
        }
        if (pairFactory != address(FACTORY)) return false;

        try pair.token0() returns (address value) {
            token0 = value;
        } catch {
            return false;
        }
        try pair.token1() returns (address value) {
            token1 = value;
        } catch {
            return false;
        }
        if (token0 == address(0) || token1 == address(0) || token0 == token1) return false;

        try FACTORY.getPair(token0, token1) returns (address canonical) {
            return canonical == candidate;
        } catch {
            return false;
        }
    }

    function _collectFee() private {
        if (feeExempt[msg.sender]) {
            require(msg.value == 0, "locker: exempt sends no fee");
            return;
        }
        require(msg.value == FEE, "locker: wrong fee");
        (bool ok,) = TREASURY.call{value: msg.value}("");
        require(ok, "locker: fee transfer failed");
    }
}

